 fresh=load('fresh-command-results.json');assert [x['check'] for x in fresh]==['contract','model','source','profile','dependency','inventory'] and all(x['exit_code']==0 and not (u/x['stderr']).read_bytes() for x in fresh)
 inv=load('current-inventory.json');p=load('authority-profile-checks.json');d=load('dependency-graph.json');old=load('types-logic-receipt.json');assert inv['partial_drafts']==77 and inv['source_owner_accepted_whole_translations']==inv['whole_definition_proofs']==0
 text=(u/'REVIEW.md').read_text().replace('# Review: typed candidate review','# Review: full partial candidate delivery review',1);a=text.index('## 12.');z=text.index('## 13.',a);diagram=text[text.index('```mermaid\n',a):text.index('```\n',text.index('```mermaid\n',a)+12)+4]
